CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY,login text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,role role NOT NULL DEFAULT 'user',email text UNIQUE,created_at timestamptz NOT NULL DEFAULT now()); 
CREATE TABLE IF NOT EXISTS tasks(id bigserial PRIMARY KEY,title text NOT NULL,description text,deadline timestamptz NOT NULL,priority priority NOT NULL,importance int NOT NULL CHECK(importance BETWEEN 1 AND 10),complexity int NOT NULL CHECK(complexity BETWEEN 1 AND 10),assignee_id bigint REFERENCES users(id),status status NOT NULL DEFAULT 'new',quadrant smallint NOT NULL DEFAULT 4,created_by bigint NOT NULL REFERENCES users(id),team_id bigint,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); 
